:root {
  /* Colors */
  --color-paper-canvas: #faf9f5;
  --color-linen-surface: #f5f4ed;
  --color-parchment-fill: #e8e6dc;
  --color-carbon-panel: #262624;
  --color-ink: #141413;
  --color-graphite-ink: #30302e;
  --color-charcoal-nav: #3d3d3a;
  --color-slate-caption: #5e5d59;
  --color-pebble-meta: #87867f;
  --color-ash-footnote: #b0aea5;
  --color-sand-border: #dedcd1;

  /* Typography — Font Families */
  --font-anthropic-sans: "anthropicSans", "DM Sans", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-anthropic-serif: "anthropicSerif", "Source Serif 4", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;

  /* Typography — Scale */
  --text-small: 11px;
  --leading-small: 1.5;
  --tracking-small: 0.2px;
  --text-caption: 13px;
  --leading-caption: 1.54;
  --tracking-caption: 0.13px;
  --text-body-sm: 15px;
  --leading-body-sm: 1.5;
  --tracking-body-sm: 0px;
  --text-body: 17px;
  --leading-body: 1.53;
  --tracking-body: 0px;
  --text-heading-sm: 22px;
  --leading-heading-sm: 1.25;
  --tracking-heading-sm: 0px;
  --text-heading-lg: 48px;
  --leading-heading-lg: 1.25;
  --tracking-heading-lg: -0.48px;
  --text-display: 61px;
  --leading-display: 1.08;
  --tracking-display: 0px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-36: 36px;
  --spacing-48: 48px;
  --spacing-80: 80px;
  --spacing-224: 224px;

  /* Layout */
  --page-max-width: 1920px;
  --prose-max-width: 616px;
  --page-gutter: 80px;
  --section-gap: 80px;
  --card-padding: 32px;
  --element-gap: 16px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 10px;
  --radius-xl: 16px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-cards: 16px;
  --radius-pills: 9999px;
  --radius-buttons: 10px;
  --radius-inputs: 8px;
  --radius-badges: 9999px;
  --radius-small-elements: 8px;
  --radius-small-cards: 4px;
  --radius-images: 0px;

  /* Shadows */
  /* none measured: elevation is tonal (see Surfaces) */

  /* Surfaces */
  --surface-paper-canvas: #faf9f5;
  --surface-linen-surface: #f5f4ed;
  --surface-parchment-fill: #e8e6dc;
  --surface-carbon-panel: #262624;
  --surface-ink: #141413;
}

